    "verify_code": "import numpy as np\nfreq = [6, 18, 21, 19, 11, 4, 1]\ncum = np.cumsum(freq).tolist()\nprint('Kumulatiewe frekwensies:', cum)\nupper_bounds = [7, 9, 11, 13, 15, 17, 19]\npoints = [(5, 0)] + list(zip(upper_bounds, cum))\nprint('Ogief punte:', points)",
